use std::collections::HashMap;use crate::ast::{ConditionalAction,Program,Statement};use crate::{Attention,Edge,EpistemicGraph,NodeId,NodeKind,Relation,StopReason};
#[derive(Debug,Clone,PartialEq,Eq)]pub struct ResourceLedger{pub initial:u64,pub remaining:u64,pub spent:u64,pub exhausted:bool}#[derive(Debug,Clone,PartialEq,Eq)]pub struct EpistemicSnapshot{pub nodes:HashMap<NodeId,NodeKind>,pub edges:Vec<Edge>,pub resources:Option<ResourceLedger>}#[derive(Debug,Clone,PartialEq,Eq)]pub struct InferenceRule{pub premises:Vec<NodeId>,pub conclusion:NodeId}#[derive(Debug,Clone,PartialEq,Eq)]pub struct ChoicePoint{pub options:Vec<String>,pub retaining:Vec<NodeId>,pub selected:Option<String>}
#[derive(Debug,Clone,PartialEq,Eq)]pub enum EventKind{BudgetDeclared{units:u64},Examined{caveat:NodeId,cost:u64,remaining:u64},Inferred{rule:String,conclusion:NodeId,premises:Vec<NodeId>},ChoiceOffered{name:String,options:Vec<String>},ChoiceSelected{name:String,option:String,commitment:NodeId},ConditionalApplied{because_action:String},Committed{commitment:NodeId,retained:Vec<NodeId>,reason:StopReason,snapshot:EpistemicSnapshot},Reopened{commitment:NodeId,because:NodeId}}#[derive(Debug,Clone,PartialEq,Eq)]pub struct Event{pub sequence:u64,pub kind:EventKind}#[derive(Debug)]pub struct Evaluation{pub graph:EpistemicGraph,pub symbols:HashMap<String,NodeId>,pub resources:Option<ResourceLedger>,pub history:Vec<Event>,pub rules:HashMap<String,InferenceRule>,pub choices:HashMap<String,ChoicePoint>}
pub fn evaluate(program:&Program)->Result<Evaluation,String>{let mut g=EpistemicGraph::new();let mut sy=HashMap::new();let mut res=None;let mut history=vec![];let mut rules=HashMap::new();let mut choices=HashMap::new();let mut seq=1;macro_rules! event{($k:expr)=>{{history.push(Event{sequence:seq,kind:$k});seq+=1;}}}for st in &program.statements{match st{Statement::Budget{units}=>{if res.is_some(){return Err("budget already defined".into())}res=Some(ResourceLedger{initial:*units,remaining:*units,spent:0,exhausted:*units==0});event!(EventKind::BudgetDeclared{units:*units});},Statement::Claim{name}=>{let i=g.add(NodeKind::Claim{proposition:name.clone()});define(&mut sy,name,i)?},Statement::Evidence{name,source}=>{let i=g.add(NodeKind::Evidence{description:name.clone(),source:source.clone()});define(&mut sy,name,i)?},Statement::Caveat{name,consequence}=>{let i=g.add_caveat(name,*consequence);define(&mut sy,name,i)?},Statement::Relate{from,relation,to}=>g.relate(resolve(&sy,from)?,*relation,resolve(&sy,to)?),Statement::Attention{caveat,state}=>g.set_attention(resolve(&sy,caveat)?,*state),Statement::Examine{caveat,cost}=>{let i=resolve(&sy,caveat)?;let r=res.as_mut().ok_or("examine cost requires a budget")?;if *cost>r.remaining{return Err(format!("insufficient budget: examination of {caveat} costs {cost}, remaining {}",r.remaining))}r.remaining-=*cost;r.spent+=*cost;r.exhausted=r.remaining==0;let remaining=r.remaining;g.set_attention(i,Attention::Examined);event!(EventKind::Examined{caveat:i,cost:*cost,remaining});},Statement::Rule{name,premises,conclusion}=>{if rules.contains_key(name){return Err(format!("duplicate rule: {name}"))}rules.insert(name.clone(),InferenceRule{premises:premises.iter().map(|n|resolve(&sy,n)).collect::<Result<Vec<_>,_>>()?,conclusion:resolve(&sy,conclusion)?});},Statement::Infer{rule}=>{let r=rules.get(rule).ok_or_else(||format!("unknown rule: {rule}"))?.clone();for p in &r.premises{g.relate(*p,Relation::Supports,r.conclusion)}event!(EventKind::Inferred{rule:rule.clone(),conclusion:r.conclusion,premises:r.premises});},Statement::Choice{name,options,retaining}=>{if choices.contains_key(name){return Err(format!("duplicate choice: {name}"))}choices.insert(name.clone(),ChoicePoint{options:options.clone(),retaining:retaining.iter().map(|n|resolve(&sy,n)).collect::<Result<Vec<_>,_>>()?,selected:None});event!(EventKind::ChoiceOffered{name:name.clone(),options:options.clone()});},Statement::Select{choice,option}=>{let cp=choices.get_mut(choice).ok_or_else(||format!("unknown choice: {choice}"))?;if cp.selected.is_some(){return Err(format!("choice already selected: {choice}"))}if !cp.options.contains(option){return Err(format!("invalid option {option} for choice {choice}"))}let id=g.commit_because(option,&cp.retaining,StopReason::Enough);define(&mut sy,option,id)?;cp.selected=Some(option.clone());event!(EventKind::ChoiceSelected{name:choice.clone(),option:option.clone(),commitment:id});let snap=EpistemicSnapshot{nodes:g.nodes.clone(),edges:g.edges.clone(),resources:res.clone()};event!(EventKind::Committed{commitment:id,retained:cp.retaining.clone(),reason:StopReason::Enough,snapshot:snap});},Statement::WhenCommitted{action,then}=>{if sy.get(action).is_some_and(|id|matches!(g.nodes.get(id),Some(NodeKind::Commitment{..}))){match then{ConditionalAction::Reopen{commitment,because}=>{let c=resolve(&sy,commitment)?;let b=resolve(&sy,because)?;g.reopen(c,b);event!(EventKind::Reopened{commitment:c,because:b});},ConditionalAction::Relate{from,relation,to}=>g.relate(resolve(&sy,from)?,*relation,resolve(&sy,to)?)}event!(EventKind::ConditionalApplied{because_action:action.clone()});}},Statement::Commit{action,reason,retaining}=>{if matches!(reason,StopReason::BudgetExhausted)&&!res.as_ref().map(|r|r.exhausted).unwrap_or(false){return Err("budget commitment requires exhausted budget".into())}let ids=retaining.iter().map(|n|resolve(&sy,n)).collect::<Result<Vec<_>,_>>()?;let i=g.commit_because(action,&ids,reason.clone());define(&mut sy,action,i)?;let snap=EpistemicSnapshot{nodes:g.nodes.clone(),edges:g.edges.clone(),resources:res.clone()};event!(EventKind::Committed{commitment:i,retained:ids,reason:reason.clone(),snapshot:snap});},Statement::Reopen{commitment,because}=>{let c=resolve(&sy,commitment)?;let b=resolve(&sy,because)?;g.reopen(c,b);event!(EventKind::Reopened{commitment:c,because:b});}}}let _=seq;Ok(Evaluation{graph:g,symbols:sy,resources:res,history,rules,choices})}
fn define(s:&mut HashMap<String,NodeId>,n:&str,i:NodeId)->Result<(),String>{if s.insert(n.into(),i).is_some(){Err(format!("duplicate symbol: {n}"))}else{Ok(())}}fn resolve(s:&HashMap<String,NodeId>,n:&str)->Result<NodeId,String>{s.get(n).copied().ok_or_else(||format!("unknown symbol: {n}"))}
#[cfg(test)]mod tests{use super::*;#[test]fn conditional_only_fires_for_actual_commitment(){let src="claim x; caveat c consequence material; choice door options open, wait retaining c; select door wait; evidence smoke from detector; when_committed open smoke opposes x; when_committed wait smoke supports x;";let e=evaluate(&crate::parser::parse(src).unwrap()).unwrap();let smoke=e.symbols["smoke"];let x=e.symbols["x"];assert!(e.graph.edges.iter().any(|z|z.from==smoke&&z.to==x&&z.relation==Relation::Supports));assert!(!e.graph.edges.iter().any(|z|z.from==smoke&&z.to==x&&z.relation==Relation::Opposes));assert_eq!(e.history.iter().filter(|z|matches!(z.kind,EventKind::ConditionalApplied{..})).count(),1);}}
